parameters.jsCode:
const body = $json.body;
const message = body.message;

if (!message || !message.audio) {
  throw new Error('No audio message found');
}

return [{
  json: {
    chat_id: message.chat.id,
    message_id: message.message_id,

    username: message.chat.username || null,
    first_name: message.chat.first_name || '',
    last_name: message.chat.last_name || '',

    is_premium: message.from?.is_premium || false,
    language_code: message.from?.language_code || 'en',

    audio: {
      file_id: message.audio.file_id,
      file_unique_id: message.audio.file_unique_id,
      file_name: message.audio.file_name || '',
      mime_type: message.audio.mime_type || 'audio/mpeg',
      title: message.audio.title || '',
      performer: message.audio.performer || '',
      duration: message.audio.duration || 0,
      file_size: message.audio.file_size || 0,
      thumbnail_file_id: message.audio.thumbnail?.file_id || ''
    },

    raw_body: body
  }
}];

